	// is still owed. Unset means two seconds.
	DispatchResend *durationpb.Duration
	// How often expired reads are swept and closed. Unset means thirty
	// seconds. It is separate from dispatch_resend because listing every key is
	// far more work than enforcing deadlines needs.
	ReadSweep *durationpb.Duration
	// How often an open submission stream restates the edge's authority. Unset
	// means the service default.
	SubmissionPulse *durationpb.Duration
